def findColoredRoot(edges, colors):
    n = len(colors)
    # map colors so that the cycle R -> B -> W -> R is +1 modulo 3
    value = {'R': 0, 'B': 1, 'W': 2}

    indeg = [0] * n   # number of edges forced to point into each node
    deg = [0] * n     # plain degree of each node

    for u, v in edges:
        deg[u] += 1
        deg[v] += 1
        diff = (value[colors[v]] - value[colors[u]]) % 3
        if diff == 1:
            indeg[v] += 1      # u -> v: v is a child of u
        elif diff == 2:
            indeg[u] += 1      # v -> u: u is a child of v
        else:
            return -1          # equal colors can never be parent and child

    # the root is the unique node with no incoming edge
    root = -1
    for i in range(n):
        if indeg[i] == 0:
            if root != -1:
                return -1      # two candidates: not a single-rooted orientation
            root = i

    # no candidate, or the root would have three children
    if root == -1 or deg[root] > 2:
        return -1
    return root
